const WidgetCard: React.FC<{ children: React.ReactNode, delay: number, frame: number, fps: number, s: number, width?: number }> = ({ children, delay, frame, fps, s, width = 280 }) => {
  const scale = spring({ frame: frame - delay, fps, config: { damping: 14 } });
  const bobY = Math.sin((frame - delay) / 20) * 10 * s;
  const isVisible = frame >= delay;

  return (
    <div style={{
      background: 'white',
      borderRadius: 24 * s,
      padding: 30 * s,
      boxShadow: `0 ${10 * s}px ${30 * s}px rgba(0,0,0,0.25)`,
      transform: `translateY(${bobY}px) scale(${scale})`,
      opacity: isVisible ? 1 : 0,
      width: width * s,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'flex-start',
      transition: "none",
      pointerEvents: "none"
    }}>
      {children}
    </div>
  );
};

